Here is the commit message:
fix error introduced by 315a64b1bd6

Here is the root cause:
The bug was caused by an overly restrictive condition that prevented the snake from changing direction when its length was greater than 1. This restriction led to unintended behavior in the game, as the snake could not navigate properly, especially when trying to turn in a valid direction. The logic did not account for the need to allow direction changes regardless of the snake's length, which is essential for gameplay.

Here is the patch:

 void mv_snake(enum dir dir)
 {
 	int y = S.y[S.ihead];
 	int x = S.x[S.ihead];

 	/* prevent movement inside oneself */
-	if (S.len > 1) {
 		if      (dir == LEFT  && S.dir == RIGHT)
 			S.dir = RIGHT;
 		else if (dir == RIGHT && S.dir == LEFT)
 			S.dir = LEFT;
 		else if (dir == UP    && S.dir == DOWN)
 			S.dir = DOWN;
 		else if (dir == DOWN  && S.dir == UP)
 			S.dir = UP;
-	}
+		else
+			S.dir = dir;

 	switch(S.dir) {
 	case UP   : --y; break;
 	case LEFT : --x; break;
 	case DOWN : ++y; break;
 	case RIGHT: ++x; break;
 	}

 	++S.ihead;
 	S.ihead = rel_ind(0);
 	S.y[S.ihead] = y;
 	S.x[S.ihead] = x;
 }



